"""UI string translations for CookGPT localization."""

LOCALES = ("es", "ca", "fr", "nl", "de", "zh-Hans", "ja", "it", "pt", "ru")


def t(es, ca, fr, nl, de, zh, ja, it, pt, ru):
    return {
        "es": es,
        "ca": ca,
        "fr": fr,
        "nl": nl,
        "de": de,
        "zh-Hans": zh,
        "ja": ja,
        "it": it,
        "pt": pt,
        "ru": ru,
    }


def tu(en, es, ca, fr, nl, de, zh, ja, it, pt, ru):
    """Translation entry where the catalog key differs from the English word."""
    return {"en": en, **t(es, ca, fr, nl, de, zh, ja, it, pt, ru)}


